//! C bindings for [`kessler`]. The header is `include/kessler.h`, generated by cbindgen; regenerate it after changing
//! this file with `cbindgen --config kessler-c/cbindgen.toml --output kessler-c/include/kessler.h kessler-c`.

use std::ptr;

use kessler::InputError;
use rand::SeedableRng;
use rand::rngs::Xoshiro256PlusPlus;

/// A rocket body, for the `kind` arguments.
pub const KESSLER_ROCKET_BODY: u32 = 0;
/// A spacecraft, for the `kind` arguments.
pub const KESSLER_SPACECRAFT: u32 = 1;

/// Result of a call. Anything other than `KESSLER_STATUS_OK` leaves the output fragments empty.
#[repr(C)]
#[derive(Debug, PartialEq, Eq)]
pub enum KesslerStatus {
    Ok = 0,
    /// A mass is not positive and finite.
    InvalidMass,
    /// The minimum characteristic length is outside [1 mm, 1 m).
    InvalidMinCharacteristicLength,
    /// The impact speed is not positive and finite.
    InvalidImpactSpeed,
    /// A `kind` is not `KESSLER_ROCKET_BODY` or `KESSLER_SPACECRAFT`.
    InvalidKind,
    /// The output pointer is null.
    NullPointer,
}

/// The fragments from one event, one entry per fragment in each array, all SI. Owned by Kessler: release with
/// `kessler_fragments_free`.
#[repr(C)]
pub struct KesslerFragments {
    /// Number of fragments.
    pub len: usize,
    /// [m]
    pub characteristic_length: *mut f32,
    /// [m²/kg]
    pub am_ratio: *mut f32,
    /// [m²]
    pub area: *mut f32,
    /// [kg]
    pub mass: *mut f32,
    /// [m/s], `3 * len` values: x, y, z for each fragment in turn.
    pub delta_v: *mut f32,
}

impl KesslerFragments {
    const EMPTY: Self = Self {
        len: 0,
        characteristic_length: ptr::null_mut(),
        am_ratio: ptr::null_mut(),
        area: ptr::null_mut(),
        mass: ptr::null_mut(),
        delta_v: ptr::null_mut(),
    };
}

fn leak(v: Vec<f32>) -> *mut f32 {
    Box::into_raw(v.into_boxed_slice()).cast()
}

/// Safety: `p` came from `leak` with `len` values, or is null.
unsafe fn reclaim(p: *mut f32, len: usize) {
    if !p.is_null() {
        drop(unsafe { Box::from_raw(ptr::slice_from_raw_parts_mut(p, len)) });
    }
}

fn kind(kind: u32) -> Option<kessler::SatKind> {
    match kind {
        KESSLER_ROCKET_BODY => Some(kessler::SatKind::RocketBody),
        KESSLER_SPACECRAFT => Some(kessler::SatKind::Spacecraft),
        _ => None,
    }
}

/// Writes the result to `out`, which must be valid for writes when non-null.
unsafe fn finish(out: *mut KesslerFragments, result: Result<kessler::Fragments, KesslerStatus>) -> KesslerStatus {
    let Some(out) = (unsafe { out.as_mut() }) else {
        return KesslerStatus::NullPointer;
    };
    match result {
        Ok(f) => {
            *out = KesslerFragments {
                len: f.mass.len(),
                characteristic_length: leak(f.characteristic_length),
                am_ratio: leak(f.am_ratio),
                area: leak(f.area),
                mass: leak(f.mass),
                delta_v: leak(f.delta_v.into_iter().flatten().collect()),
            };
            KesslerStatus::Ok
        }
        Err(status) => {
            *out = KesslerFragments::EMPTY;
            status
        }
    }
}

impl From<InputError> for KesslerStatus {
    fn from(e: InputError) -> Self {
        match e {
            InputError::Mass => Self::InvalidMass,
            InputError::MinCharacteristicLength => Self::InvalidMinCharacteristicLength,
            InputError::ImpactSpeed => Self::InvalidImpactSpeed,
        }
    }
}

/// Breaks up a single object. Inputs and outputs are SI (m, kg, m/s); a given `seed` gives the same fragments as the
/// Python and JavaScript packages.
///
/// # Safety
/// `out` must be null or valid for writes. On success, free it with `kessler_fragments_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kessler_explosion(
    mass: f32,
    kind: u32,
    min_characteristic_length: f32,
    seed: u64,
    out: *mut KesslerFragments,
) -> KesslerStatus {
    let result = self::kind(kind).ok_or(KesslerStatus::InvalidKind).and_then(|kind| {
        let mut rng = Xoshiro256PlusPlus::seed_from_u64(seed);
        Ok(kessler::explosion(mass, kind, min_characteristic_length, &mut rng)?)
    });
    unsafe { finish(out, result) }
}

/// Breaks up two objects colliding at `impact_speed`. Inputs and outputs are SI (m, kg, m/s); a given `seed` gives the
/// same fragments as the Python and JavaScript packages.
///
/// # Safety
/// `out` must be null or valid for writes. On success, free it with `kessler_fragments_free`.
#[unsafe(no_mangle)]
#[allow(clippy::too_many_arguments)]
pub unsafe extern "C" fn kessler_collision(
    mass_a: f32,
    kind_a: u32,
    mass_b: f32,
    kind_b: u32,
    impact_speed: f32,
    min_characteristic_length: f32,
    seed: u64,
    out: *mut KesslerFragments,
) -> KesslerStatus {
    let result = kind(kind_a)
        .zip(kind(kind_b))
        .ok_or(KesslerStatus::InvalidKind)
        .and_then(|(kind_a, kind_b)| {
            let mut rng = Xoshiro256PlusPlus::seed_from_u64(seed);
            Ok(kessler::collision(
                mass_a,
                kind_a,
                mass_b,
                kind_b,
                impact_speed,
                min_characteristic_length,
                &mut rng,
            )?)
        });
    unsafe { finish(out, result) }
}

/// Frees fragments from `kessler_explosion` or `kessler_collision` and empties them, so a second call is harmless.
///
/// # Safety
/// `fragments` must be null or point to fragments written by Kessler (or emptied by this function).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn kessler_fragments_free(fragments: *mut KesslerFragments) {
    let Some(f) = (unsafe { fragments.as_mut() }) else {
        return;
    };
    unsafe {
        reclaim(f.characteristic_length, f.len);
        reclaim(f.am_ratio, f.len);
        reclaim(f.area, f.len);
        reclaim(f.mass, f.len);
        reclaim(f.delta_v, 3 * f.len);
    }
    *f = KesslerFragments::EMPTY;
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::slice;

    #[test]
    fn matches_the_rust_api_and_frees() {
        let mut out = KesslerFragments::EMPTY;
        let status = unsafe { kessler_explosion(839.0, KESSLER_ROCKET_BODY, 0.1, 7, &mut out) };
        assert_eq!(status, KesslerStatus::Ok);

        let expected = kessler::explosion(
            839.0,
            kessler::SatKind::RocketBody,
            0.1,
            &mut Xoshiro256PlusPlus::seed_from_u64(7),
        )
        .unwrap();
        assert_eq!(out.len, expected.mass.len());
        assert_eq!(unsafe { slice::from_raw_parts(out.mass, out.len) }, expected.mass);
        let dv: Vec<f32> = expected.delta_v.into_iter().flatten().collect();
        assert_eq!(unsafe { slice::from_raw_parts(out.delta_v, 3 * out.len) }, dv);

        unsafe { kessler_fragments_free(&mut out) };
        assert!(out.mass.is_null() && out.len == 0);
        unsafe { kessler_fragments_free(&mut out) }; // second free is a no-op
    }

    #[test]
    fn reports_bad_input() {
        let mut out = KesslerFragments::EMPTY;
        let explode = |mass, kind, out| unsafe { kessler_explosion(mass, kind, 0.1, 0, out) };
        assert_eq!(explode(-1.0, KESSLER_SPACECRAFT, &mut out), KesslerStatus::InvalidMass);
        assert_eq!(explode(1.0, 9, &mut out), KesslerStatus::InvalidKind);
        assert_eq!(
            explode(1.0, KESSLER_SPACECRAFT, ptr::null_mut()),
            KesslerStatus::NullPointer
        );
        let status = unsafe { kessler_collision(1.0, 0, 1.0, 1, 0.0, 0.1, 0, &mut out) };
        assert_eq!(status, KesslerStatus::InvalidImpactSpeed);
        assert!(out.mass.is_null());
    }
}
